// ------------------------------------------------------------------ 4. scales

function assertScale(scale: ChartScale, message: string): void {
  assert.ok(Number.isFinite(scale.min) && Number.isFinite(scale.max) && Number.isFinite(scale.step), `${message}: finite ends and step (${scale.min}, ${scale.max}, ${scale.step})`);
  assert.ok(scale.max > scale.min, `${message}: the maximum ${scale.max} lies above the minimum ${scale.min}`);
  assert.ok(scale.step > 0, `${message}: a step above zero (${scale.step})`);
  assert.ok(Number.isFinite(scale.max - scale.min), `${message}: a length that is a number`);
  assert.ok(scale.ticks.length >= 1 && scale.ticks.length <= MAX_AXIS_TICKS + 1, `${message}: ${scale.ticks.length} ticks`);
  for (let i = 0; i < scale.ticks.length; i++) {
    assert.ok(Number.isFinite(scale.ticks[i]), `${message}: tick ${i} is a number`);
    if (i > 0) assert.ok(scale.ticks[i] > scale.ticks[i - 1], `${message}: the ticks go upwards`);
  }
}

test('scale: numbers at the edge of what a number can be still give an axis', () => {
  const cases: [number, number, { min?: number; max?: number; step?: number; maxSteps?: number }][] = [
    [0, 0, {}],
    [1e308, 1.7e308, {}],
    [-1.7e308, 1.7e308, {}],
    [1.7e308, 1.7e308, {}],
    [5e-324, 1e-323, {}],
    [1e-320, 3e-320, {}],
    [0, 10, { step: 1e-300 }],
    [0, 10, { step: 1e-320 }],
    [0, 10, { step: 5e-324 }],
    [0, 10, { step: 1e300 }],
    [0, 10, { step: 1.7e308 }],
    [0, 1, { min: 5, max: 1 }],
    [0, 1, { min: 5, max: 1, step: 1e-320 }],
    [0, 1, { min: 1e308 }],
    [0, 1, { max: -1e308 }],
    [0, 1, { min: -1.7e308, max: 1.7e308 }],
    [0, 10, { min: 0, max: 1e-300 }],
    [0, 10, { min: 1, max: 1 + 1e-15 }],
    [1e15, 1e15 + 1, {}],
    [1e15, 1e15 + 1, { step: 0.001 }],
    [-1e300, 1e300, { step: 1 }],
    [NaN, Infinity, {}],
    [-Infinity, NaN, { min: NaN, max: Infinity, step: -Infinity }],
    [3, 3, { maxSteps: 0 }],
    [3, 3, { maxSteps: NaN }],
    [0, 1, { min: Infinity }],
    [0, 1, { max: NaN }],
    [1e300, 1e300, { min: 1e300 }],
    [-1e300, -1e300, { max: -1e300 }],
  ];
  for (const [low, high, options] of cases) assertScale(chartScale(low, high, options), `chartScale(${low}, ${high}, ${JSON.stringify(options)})`);
});

test('scale: what the axis states and cannot be is not taken, and the axis works it out by itself', () => {
  const auto = chartScale(0, 30);
  assert.deepEqual(chartScale(0, 30, { min: 1e308 }), auto, 'a minimum too large to count with');
  assert.deepEqual(chartScale(0, 30, { max: -1.7e308 }), auto, 'a maximum too far below');
  assert.deepEqual(chartScale(0, 30, { min: NaN, max: Infinity }), auto, 'ends that are no numbers');
  assert.deepEqual(chartScale(0, 30, { min: 5, max: 1, step: 1e-320 }), auto, 'ends the wrong way round and a step that is next to nothing');
  assert.deepEqual(chartScale(0, 30, { step: 1e-300 }), auto, 'a step far too small for the range');
  assert.deepEqual(chartScale(0, 30, { step: 5e-324 }), auto);
  // A step somewhat too small is kept as what its ticks are counted in.
  const fine = chartScale(0, 1000, { step: 1 });
  assert.equal(fine.step, 8, 'doubled until the ticks fit');
  assert.ok(fine.ticks.length <= MAX_AXIS_TICKS + 1 && fine.ticks.length > 100, `${fine.ticks.length} ticks`);
  // What can be is still taken as it is.
  assert.deepEqual([chartScale(0, 30, { min: 10, max: 50 }).min, chartScale(0, 30, { min: 10, max: 50 }).max], [10, 50]);
  assert.deepEqual(chartScale(0, 30, { min: 0, max: 1e-300 }).max, 1e-300, 'a very small range that is one');
  assert.deepEqual([chartScale(0, 10, { min: -1e300, max: 1e300 }).min, chartScale(0, 10, { min: -1e300, max: 1e300 }).max], [-1e300, 1e300], 'the largest ends that are taken');
  // Data too large to add up is drawn at the largest numbers that can be.
  const huge = chartScale(-1.7e308, 1.7e308);
  assert.ok(huge.min <= -1e300 && huge.max >= 1e300, `an axis as long as numbers allow (${huge.min}..${huge.max})`);
});

/** Every number a layout holds is a finite one. */
function assertFinite(layout: ChartLayout, message: string): void {
  const check = (value: unknown, where: string): void => {
    if (typeof value === 'number') assert.ok(Number.isFinite(value), `${message}: ${where} is ${value}`);
    else if (Array.isArray(value)) for (let i = 0; i < value.length; i++) check(value[i], `${where}[${i}]`);
    else if (value && typeof value === 'object') for (const key of Object.keys(value)) check((value as Record<string, unknown>)[key], `${where}.${key}`);
  };
  check([layout.width, layout.height, layout.radius], 'the frame');
  check(layout.plot, 'plot');
  if (layout.scale) assertScale(layout.scale, `${message}: scale`);
  if (layout.xScale) assertScale(layout.xScale, `${message}: xScale`);
  for (let i = 0; i < layout.items.length; i++) check(layout.items[i], `item ${i} (${layout.items[i].kind}/${(layout.items[i] as { role?: string }).role || ''})`);
}

test('layout: whatever the series and the axes state, no number of a layout is anything but finite (many seeds)', () => {
  const special: (() => (number | null)[])[] = [
    () => [0, 0, 0],
    () => [5],
    () => [-3, -1, -7],
    () => [1e308, 1e308],
    () => [1.7e308, -1.7e308],
    () => [1e308, 1.7e308],
    () => [1e-308, 2e-308],
    () => [null, null],
    () => [],
    () => [null, 3, null, 4, null],
    () => [1e300, -1e-300, 0],
    () => [5e-324, 0],
    () => [100, 100, 100],
    () => [-0, 0],
    () => [99.5, 100, 99.9],
    () => [-1.7e308, -1.7e308, -1.7e308],
  ];
  const scalings = ['', '<c:max val="1"/><c:min val="5"/>', '<c:min val="-10"/>', '<c:max val="3"/>', '<c:logBase val="10"/>', '<c:min val="1e308"/>', '<c:max val="-1e308"/>', '<c:max val="1e-300"/><c:min val="0"/>', '<c:max val="1.7e308"/><c:min val="-1.7e308"/>', '<c:min val="5e-324"/>', '<c:max val="7"/><c:min val="7"/>'];
  const units = ['', '<c:majorUnit val="0"/>', '<c:majorUnit val="-1"/>', '<c:majorUnit val="1e-12"/>', '<c:majorUnit val="1e-320"/>', '<c:majorUnit val="1e300"/>', '<c:majorUnit val="1.7e308"/>', '<c:majorUnit val="0.3"/>'];
  const crossings = ['', '<c:crosses val="max"/>', '<c:crosses val="min"/>', '<c:crossesAt val="1e308"/>', '<c:crossesAt val="-1.7e308"/>'];
  const sizes: [number, number][] = [[480, 300], [0, 0], [-5, 100], [1, 1], [79, 59], [100, 100], [3000, 20], [20, 3000], [1e9, 1e9], [NaN, 100], [200.5, 133.3], [181, 121]];
  const kinds = ['bar', 'barH', 'line', 'area', 'pie', 'doughnut', 'scatter', 'combo'];
  let checked = 0;
  for (let seed = 1; seed <= 12; seed++) {
    let state = seed * 7919;
    const random = () => (state = (state * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
    const pick = <T>(list: T[]): T => list[Math.floor(random() * list.length) % list.length];
    const data = (): (number | null)[] => {
      if (random() < 0.4) return pick(special)();
      const scale = Math.pow(10, Math.floor(random() * 620 - 310));
      const sign = random();
      return Array.from({ length: Math.floor(random() * 8) }, () => (random() < 0.1 ? null : (random() - (sign < 0.3 ? 0.5 : sign < 0.4 ? 1 : 0)) * scale));
    };
    for (let round = 0; round < 250; round++) {
      const kind = pick(kinds);
      const grouping = pick(['standard', 'stacked', 'percentStacked']);
      const series: (number | null)[][] = Array.from({ length: Math.floor(random() * 4) + (round % 5 === 0 ? 0 : 1) }, data);
      const axes = catAx(pick(crossings)) + valAx('<c:majorGridlines/><c:minorGridlines/>' + pick(units) + pick(['', '<c:crossBetween val="midCat"/>']), `<c:orientation val="${pick(['minMax', 'maxMin'])}"/>` + pick(scalings));
      const xy = (list: (number | null)[][], from: number) => list.map((values, i) => xySer(from + i, { cat: random() < 0.2 ? undefined : numLit(values.map((_value, j) => (random() < 0.1 ? null : pick([j, j * 1e305, -j * 1e-310, j + random()])))), val: numLit(values) })).join('');
      let plot: string;
      if (kind === 'scatter') {
        plot =
          group('scatterChart', '<c:scatterStyle val="lineMarker"/>', xy(series, 0)) +
          `<c:valAx><c:axId val="111"/><c:scaling>${pick(scalings)}</c:scaling><c:axPos val="${pick(['b', 'l'])}"/>${pick(units)}<c:crossAx val="222"/></c:valAx>` +
          `<c:valAx><c:axId val="222"/><c:scaling>${pick(scalings)}</c:scaling><c:axPos val="l"/><c:majorGridlines/>${pick(units)}<c:crossAx val="111"/></c:valAx>`;
      } else if (kind === 'pie' || kind === 'doughnut') plot = group(`${kind}Chart`, '<c:varyColors val="1"/>', series.map((values, i) => ser(i, { val: numLit(values) })).join(''), '', false);
      else if (kind === 'combo') {
        const half = Math.ceil(series.length / 2);
        plot =
          group(pick(['barChart', 'lineChart', 'areaChart']), `<c:barDir val="${pick(['col', 'bar'])}"/><c:grouping val="${grouping}"/>`, series.slice(0, half).map((values, i) => ser(i, { val: numLit(values) })).join('')) +
          group('scatterChart', '<c:scatterStyle val="lineMarker"/>', xy(series.slice(half), half)) +
          axes;
      } else {
        const type = kind === 'barH' ? 'bar' : kind;
        const head = (type === 'bar' ? `<c:barDir val="${kind === 'barH' ? 'bar' : 'col'}"/>` : '') + `<c:grouping val="${type === 'bar' && grouping === 'standard' ? 'clustered' : grouping}"/>`;
        plot = group(`${type}Chart`, head, series.map((values, i) => ser(i, { val: numLit(values) })).join('')) + axes;
      }
      const xml = chartXml({ head: title('T'), plot, tail: legend(pick(['r', 'b', 't', 'l'])) + `<c:plotVisOnly val="1"/><c:dispBlanksAs val="${pick(['gap', 'zero', 'span'])}"/>` });
      const chart = readChart(xml);
      if (!chart) continue;
      const [width, height] = pick(sizes);
      const spec = `seed ${seed}, round ${round}: ${kind} ${grouping} ${width}x${height} ${JSON.stringify(series)} ${plot.replace(/<c:ser>.*<\/c:ser>/, '')}`;
      let layout: ChartLayout | undefined;
      assert.doesNotThrow(() => (layout = layoutChart(chart, chartValues(chart), width, height, fakeMeasure)), spec);
      assertFinite(layout as ChartLayout, spec);
      checked++;
    }
  }
  assert.ok(checked > 2500, `${checked} layouts were looked at`);
});

// ----------------------------------------------- 5. stacked lines and areas

const lineOf = (grouping: string, series: string, type = 'lineChart') => chartXml({ plot: group(type, `<c:grouping val="${grouping}"/>`, series, type === 'lineChart' ? '<c:marker val="1"/>' : '') + catAx() + valAx() });
const first = (values: (number | null)[]) => ser(0, { cat: CATS, val: numLit(values) });
const second = (values: (number | null)[]) => ser(1, { cat: CATS, val: numLit(values) });

test('stacked lines of mixed signs add up one after another; stacked bars keep a pile on either side of zero', () => {
  // UNSURE: with 10 and then -3 the second line runs at 7 (a bar would hang at -3 below zero).
  const lines = lay(lineOf('stacked', first([10, 10, -4]) + second([-3, 5, -2])));
  const paths = items(lines, 'path', 'line');
  assert.equal(paths.length, 2);
  const ys = (index: number) => paths[index].points.filter((_value, i) => i % 2 === 1);
  [10, 10, -4].forEach((value, i) => near(ys(0)[i], valueY(lines, value), `the first line at ${value}`));
  [7, 15, -6].forEach((value, i) => near(ys(1)[i], valueY(lines, value), `the second line at the sum ${value}`));
  const scale = lines.scale as ChartScale;
  assert.ok(scale.max >= 15 && scale.min <= -6, `the axis holds the sums (${scale.min}..${scale.max})`);
  assert.ok(scale.min > -15, 'and not a pile of the negative values alone');

  // An area stands on the series before it, wherever that runs.
  const areas = lay(lineOf('stacked', first([10, 10, -4]) + second([-3, 5, -2]), 'areaChart'));
  const area = items(areas, 'path', 'area').filter((item) => item.series === 1)[0];
  // The outline runs along the top (three points) and back along what it stands on.
  [7, 15, -6].forEach((value, i) => near(area.points[i * 2 + 1], valueY(areas, value), `the top of the second area at ${value}`));
  [-4, 10, 10].forEach((value, i) => near(area.points[6 + i * 2 + 1], valueY(areas, value), `it stands on the first series at ${value}`));

  // Bars: what is below zero hangs below zero, on its own pile.
  const bars = lay(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="stacked"/>', first([10, 10, -4]) + second([-3, 5, -2]), '<c:overlap val="100"/>') + catAx() + valAx() }));
  const b = items(bars, 'rect', 'bar').filter((bar) => bar.series === 1);
  near(b[0].y, valueY(bars, 0), 'the bar of -3 hangs from zero');
  near(b[0].y + b[0].height, valueY(bars, -3), 'down to -3, not at 7');
  near(b[1].y, valueY(bars, 15), 'the bar of 5 stands on the 10 below it');
});

test('100 % stacked lines: shares of the sizes, added up one after another', () => {
  // UNSURE: a share is a share of the absolute values, as for bars; the line then runs at the sum of the shares.
  const layout = lay(lineOf('percentStacked', first([10, 1]) + second([-10, 3])));
  const paths = items(layout, 'path', 'line');
  const ys = (index: number) => paths[index].points.filter((_value, i) => i % 2 === 1);
  near(ys(0)[0], valueY(layout, 0.5), '10 of 20');
  near(ys(1)[0], valueY(layout, 0), 'and -10 of 20 back down to nothing');
  near(ys(0)[1], valueY(layout, 0.25), '1 of 4');
  near(ys(1)[1], valueY(layout, 1), 'the two together are the whole');
});

