const numbered = (axis: string, cached: (number | null)[] = [1, 2, 3], code = 'General') =>
  chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { cat: numRef('Sayfa1!$A$1:$A$3', cached, code), val: numRef('Sayfa1!$B$1:$B$3', [1, 2, 3]) })) + axis + valAx() });

async function bookOf(chart: string, sheet: string, head?: string): Promise<{ workbook: Workbook; chart: Chart }> {
  const workbook = await (await open(await chartWorkbook({ sheet, drawing: twoCell([4, 0], [10, 14], chartFrameOf('rIdC1')), charts: [chart], workbookHead: head }))).workbook();
  return { workbook, chart: (workbook.sheets[0].drawings![0].object as DrawingChart).chart };
}

test('category labels: a format the axis states as its own formats numbers and dates of the cells; otherwise the cells show what they show', async () => {
  const cells = '<sheetData><row r="1"><c r="A1"><v>1.5</v></c><c r="B1"><v>1</v></c></row><row r="2"><c r="A2" t="d"><v>2024-03-05</v></c><c r="B2"><v>2</v></c></row><row r="3"><c r="A3" t="inlineStr"><is><t>metin</t></is></c><c r="B3"><v>3</v></c></row></sheetData>';
  const labels = async (axis: string): Promise<string[]> => {
    const { workbook, chart } = await bookOf(numbered(axis), cells);
    const values = chartValues(chart, { workbook });
    return [values.label(0), values.label(1), values.label(2)];
  };
  const shown = await labels(catAx());
  assert.equal(shown[0], '1.5');
  assert.equal(shown[2], 'metin');
  assert.deepEqual(await labels(catAx('<c:numFmt formatCode="0.00" sourceLinked="0"/>')), ['1.50', '45356.00', 'metin'], 'not linked to the source: the format of the axis; a text stays a text');
  assert.deepEqual(await labels(catAx('<c:numFmt formatCode="yyyy-mm-dd" sourceLinked="0"/>', 'dateAx')), ['1900-01-01', '2024-03-05', 'metin'], 'a date format on a date axis');
  assert.deepEqual(await labels(catAx('<c:numFmt formatCode="0.00" sourceLinked="1"/>')), shown, 'linked to the source: what the cells show');
  assert.deepEqual(await labels(catAx('<c:numFmt formatCode="0.00"/>')), shown, 'nothing said about the source: what the cells show');
  // UNSURE: "General" that is not linked is written by other programs for every axis; the cells are shown as they are.
  assert.deepEqual(await labels(catAx('<c:numFmt formatCode="General" sourceLinked="0"/>')), shown, 'General is no format of its own');
  assert.deepEqual(await labels(catAx('<c:numFmt formatCode="" sourceLinked="0"/>')), shown, 'no format code');

  // Without the cells: the cached numbers in the format of the axis, else in the one cached with them.
  const cached = (axis: string) => {
    const values = chartValues(model(numbered(axis, [1.5, 2, null], '0.0')));
    return [values.label(0), values.label(1), values.label(2)];
  };
  assert.deepEqual(cached(catAx()), ['1.5', '2.0', '']);
  assert.deepEqual(cached(catAx('<c:numFmt formatCode="0.000" sourceLinked="0"/>')), ['1.500', '2.000', '']);
  assert.deepEqual(cached(catAx('<c:numFmt formatCode="0.000" sourceLinked="1"/>')), ['1.5', '2.0', '']);
});

