test('a series gets its colour by its index (c:idx), not by its place (c:order)', () => {
  const chart = model(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { idx: 3, order: 0, val: numLit([1]) }) + ser(1, { idx: 0, order: 1, val: numLit([2]) }) + ser(2, { idx: 7, order: 2, val: numLit([3]) })) + catAx() + valAx() }));
  const layout = layoutChart(chart, chartValues(chart), 480, 320, fakeMeasure);
  const bars = items(layout, 'rect', 'bar');
  assert.deepEqual(bars.map((bar) => bar.fill), [chartAutoColor(chart, 3), chartAutoColor(chart, 0), chartAutoColor(chart, 7)]);
  assert.deepEqual(bars.map((bar) => bar.fill), ['#FFC000', '#4472C4', '#8E4B1D'], 'the fourth accent, the first, and the darker form of the second');
  assert.ok(bars[0].x < bars[1].x && bars[1].x < bars[2].x, 'drawn in the order of c:order');
  // Lines and the legend follow the same index.
  const lines = lay(lineOf('standard', ser(0, { idx: 4, order: 0, tx: '<c:v>A</c:v>', val: numLit([1, 2]) }) + ser(1, { idx: 1, order: 1, tx: '<c:v>B</c:v>', val: numLit([2, 1]) })).replace('</c:plotArea>', '</c:plotArea><c:legend><c:legendPos val="r"/></c:legend>'));
  assert.deepEqual(items(lines, 'path', 'line').map((item) => item.stroke), ['#5B9BD5', '#ED7D31']);
  assert.deepEqual(items(lines, 'path', 'swatch').map((item) => item.stroke), ['#5B9BD5', '#ED7D31'], 'the keys of the legend');
});

test('100 % stacked bars: a share is a share of the sizes of the values, positive and negative together', () => {
  const layout = lay(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="percentStacked"/>', first([1, 2, 0]) + second([-3, 2, 0]), '<c:overlap val="100"/>') + catAx() + valAx() }));
  assert.deepEqual([layout.scale?.min, layout.scale?.max], [-1, 1]);
  const bars = items(layout, 'rect', 'bar');
  const a = bars.filter((bar) => bar.series === 0);
  const b = bars.filter((bar) => bar.series === 1);
  const unit = layout.plot.height / 2;
  near(a[0].height, 0.25 * unit, '1 of |1| + |-3| is a quarter');
  near(a[0].y + a[0].height, valueY(layout, 0), 'standing on zero');
  near(b[0].height, 0.75 * unit, '-3 of 4 is three quarters');
  near(b[0].y, valueY(layout, 0), 'hanging from zero');
  near(a[1].height + b[1].height, unit, '2 and 2 fill the upper half');
  near(a[2].height + b[2].height, 0, 'nothing of nothing is nothing');
});

test('the category axis crosses where it says: at the top of the value axis the columns hang down', () => {
  const at = (inner: string) => lay(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', first([10, 20, 30])) + catAx(inner) + valAx('<c:majorGridlines/>', '<c:orientation val="minMax"/><c:max val="40"/><c:min val="0"/>') }));
  const top = at('<c:crosses val="max"/>');
  const bars = items(top, 'rect', 'bar');
  bars.forEach((bar, i) => {
    near(bar.y, top.plot.y, `column ${i} hangs from the top`);
    near(bar.height, ((40 - (i + 1) * 10) / 40) * top.plot.height, `column ${i} reaches down to its value`);
  });
  const axis = items(top, 'path', 'axis')[0];
  assert.ok(Math.abs(axis.points[1] - top.plot.y) <= 0.5 && axis.points[1] === axis.points[3], 'the line of the category axis at the top');
  const bottom = at('<c:crosses val="min"/>');
  items(bottom, 'rect', 'bar').forEach((bar, i) => near(bar.y + bar.height, bottom.plot.y + bottom.plot.height, `min: column ${i} stands on the bottom`));
  const stated = at('<c:crossesAt val="20"/>');
  const split = items(stated, 'rect', 'bar');
  near(split[0].y, valueY(stated, 20), 'crossesAt 20: the column of 10 hangs from 20');
  near(split[2].y + split[2].height, valueY(stated, 20), 'and the column of 30 stands on it');
  near(split[1].height, 0, 'the column of 20 has no height');
});

test('the legend lists at most a hundred entries, of series and of points', () => {
  assert.equal(MAX_LEGEND_ENTRIES, 100);
  let many = '';
  for (let i = 0; i < 130; i++) many += ser(i, { tx: `<c:v>S${i}</c:v>`, val: numLit([i + 1]) });
  const layout = lay(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', many) + catAx() + valAx(), tail: legend('r') }), 900, 4000);
  const entries = texts(layout, 'legend');
  assert.equal(entries.length, 100, 'room for all of them, a hundred listed');
  assert.deepEqual([entries[0], entries[99]], ['S0', 'S99']);
  assert.equal(items(layout, 'rect', 'bar').length, 130, 'every series is still drawn');
  const pie = lay(chartXml({ plot: group('pieChart', '<c:varyColors val="1"/>', ser(0, { val: numLit(Array.from({ length: 130 }, () => 1)) }), '', false), tail: legend('r') }), 900, 4000);
  assert.equal(texts(pie, 'legend').length, 100, 'a hundred slices listed');
  assert.equal(items(pie, 'slice').length, 130);
});

test('a title that would take too much of a low frame is left out, and takes no room', () => {
  const plot = group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', first([1, 2, 3])) + catAx() + valAx();
  const long = '<c:title><c:tx><c:rich><a:bodyPr/><a:p><a:r><a:t>Bir</a:t></a:r></a:p><a:p><a:r><a:t>İki</a:t></a:r></a:p><a:p><a:r><a:t>Üç</a:t></a:r></a:p></c:rich></c:tx></c:title>';
  const without = lay(chartXml({ plot }), 480, 130);
  const dropped = lay(chartXml({ head: long, plot }), 480, 130);
  assert.deepEqual(texts(dropped, 'title'), [], 'three lines do not fit 130 pixels');
  assert.deepEqual(dropped.plot, without.plot, 'the plot area is as large as without a title');
  const short = lay(chartXml({ head: title('Bir'), plot }), 480, 130);
  assert.deepEqual(texts(short, 'title'), ['Bir'], 'one line does');
  assert.ok(short.plot.height < without.plot.height, 'and takes its room');
  assert.deepEqual(texts(lay(chartXml({ head: long, plot }), 480, 400), 'title'), ['Bir', 'İki', 'Üç'], 'a higher frame shows all three lines');
});

test('dates count from 1904 where the chart or the workbook says so', async () => {
  // The cache: the chart part says how its dates count.
  const dated = (before: string) => chartXml({ before, plot: group('barChart', '<c:barDir val="col"/>', ser(0, { cat: numRef('Yok!$A$1:$A$2', [1, 2], 'yyyy-mm-dd'), val: numLit([1, 2]) })) + catAx() + valAx() });
  const usual = model(dated(''));
  const mac = model(dated('<c:date1904 val="1"/>'));
  assert.equal(usual.date1904, undefined);
  assert.equal(mac.date1904, true);
  assert.equal(chartValues(usual).label(0), '1900-01-01');
  assert.equal(chartValues(mac).label(0), '1904-01-02', 'the same number is four years and a day later');

  // The cells: the workbook says it. A date cell is the number its workbook counts it as.
  const cells = '<sheetData><row r="1"><c r="A1" t="d"><v>1904-01-02</v></c></row><row r="2"><c r="A2" t="d"><v>1904-01-03</v></c></row></sheetData>';
  const chart = chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numRef('Sayfa1!$A$1:$A$2', []) })) + catAx() + valAx('<c:numFmt formatCode="yyyy-mm-dd" sourceLinked="0"/>', '<c:orientation val="minMax"/><c:max val="2"/><c:min val="1"/>') + '' });
  const from1904 = await bookOf(chart, cells, '<workbookPr date1904="1"/>');
  const from1900 = await bookOf(chart, cells);
  assert.equal(from1904.workbook.date1904, true);
  assert.deepEqual(chartValues(from1904.chart, { workbook: from1904.workbook }).series[0].values.toArray(), [1, 2]);
  assert.deepEqual(chartValues(from1900.chart, { workbook: from1900.workbook }).series[0].values.toArray(), [1463, 1464]);
  // The labels of the value axis are formatted the way the layout is told the dates count.
  const values = chartValues(from1904.chart, { workbook: from1904.workbook });
  const ticks1904 = texts(layoutChart(from1904.chart, values, 480, 320, fakeMeasure, { date1904: true }), 'tick');
  const ticks1900 = texts(layoutChart(from1904.chart, values, 480, 320, fakeMeasure, { date1904: false }), 'tick');
  assert.equal(ticks1904[0], '1904-01-02');
  assert.equal(ticks1900[0], '1900-01-01');
});

test('painting is bounded: a chart of very many series shows fewer points of each', () => {
  // 64 series of 20,000 points each: 1.28 million points.
  const chart = model(chartXml({ plot: group('scatterChart', '<c:scatterStyle val="lineMarker"/>', xySer(0, { cat: numLit([1]), val: numLit([1]) })) + xyAxes() }));
  const index: number[] = [];
  const numbers: number[] = [];
  for (let i = 0; i < 20000; i++) {
    index.push(i);
    numbers.push(Math.sin(i / 100) * 100);
  }
  const data: ChartData = { kind: 'num', cache: { index, values: numbers }, count: 20000 };
  const template = chart.groups[0].series[0];
  const count = (layout: ChartLayout): number => {
    let total = 0;
    for (const item of layout.items) total += item.kind === 'markers' ? item.points.length / 2 : item.kind === 'rect' && item.role === 'bar' ? 1 : item.kind === 'path' && (item.role === 'line' || item.role === 'area') ? item.points.length / 2 : 0;
    return total;
  };
  for (const kind of ['scatter', 'bar', 'line', 'area'] as const) {
    chart.groups[0].kind = kind;
    chart.groups[0].series = Array.from({ length: 64 }, (_unused, i) => ({ ...template, index: i, order: i, values: data, categories: kind === 'scatter' ? data : undefined }));
    const started = Date.now();
    const values = chartValues(chart);
    assert.equal(values.series[63].values.length, 20000);
    for (const [width, height] of [[480, 300], [4000, 3000], [100000, 100000]]) {
      const drawn = count(layoutChart(chart, values, width, height, fakeMeasure));
      // Markers and lines of a scatter series are counted twice; a line that is sampled has two points per place.
      assert.ok(drawn <= MAX_DRAWN_ITEMS * 4, `${kind} at ${width}x${height}: ${drawn} things to paint`);
      assert.ok(drawn >= 64, `${kind} at ${width}x${height}: every series is still there (${drawn})`);
    }
    assert.ok(Date.now() - started < 30000, `${kind}: worked out without hanging`);
  }
  // A single series is not thinned out for the sake of others.
  chart.groups[0].kind = 'scatter';
  chart.groups[0].series = [{ ...template, values: data, categories: data }];
  const single = layoutChart(chart, chartValues(chart), 480, 300, fakeMeasure);
  const marks = items(single, 'markers', 'marker')[0].points.length / 2;
  assert.ok(marks > 400 && marks <= 1000, `one series in 480 pixels: ${marks} markers, a few per pixel`);
});
